import { useEffect } from "react";

export interface MailroomChatIdentity {
	/** Signed identity token generated by your backend (verified) */
	token?: string;
	/** Unverified visitor email (used when signed identity is not required) */
	email?: string;
	/** Unverified visitor display name */
	name?: string;
}

export interface MailroomChatProps {
	/** Your Mailroom base URL, e.g. "https://mail.yourapp.com" */
	url: string;
	/** Widget public key (mrc_…) from Inbox → Website chat */
	publicKey: string;
	/** Optional visitor identity; updates automatically when the user signs in/out */
	identity?: MailroomChatIdentity | null;
	/** Optional theme override ("light" | "dark" | null to follow widget config) */
	theme?: "light" | "dark" | null;
	/** Optional callback fired once the widget finishes mounting */
	onReady?: () => void;
}

interface MailroomChatApi {
	open: () => void;
	close: () => void;
	toggle: () => void;
	identify: (who: MailroomChatIdentity) => void;
	reset: () => void;
	unread: () => number;
	setTheme: (theme: "light" | "dark" | null) => void;
}

declare global {
	interface Window {
		MailroomChat?: MailroomChatApi;
	}
}

/**
 * Drop-in React / Next.js component for the Mailroom Website Chat, Help Center & Changelog widget.
 * Safe for SSR: loads the script on the client once and keeps identity & theme in sync.
 */
export function MailroomChat({
	url,
	publicKey,
	identity,
	theme,
	onReady,
}: MailroomChatProps): null {
	useEffect(() => {
		if (typeof document === "undefined" || !url || !publicKey) return;
		const src = `${url.replace(/\/$/, "")}/chat/${encodeURIComponent(publicKey)}.js`;
		const existing = document.querySelector<HTMLScriptElement>(
			`script[data-mailroom-chat="${publicKey}"]`,
		);

		const sync = () => {
			if (!window.MailroomChat) return;
			if (theme !== undefined) window.MailroomChat.setTheme(theme);
			if (identity && (identity.token || identity.email || identity.name)) {
				window.MailroomChat.identify(identity);
			}
			onReady?.();
		};

		if (existing) {
			sync();
			return;
		}

		const script = document.createElement("script");
		script.src = src;
		script.async = true;
		script.dataset.mailroomChat = publicKey;
		script.onload = sync;
		document.body.appendChild(script);
	}, [url, publicKey, onReady, identity, theme]);

	useEffect(() => {
		if (typeof window === "undefined" || !window.MailroomChat) return;
		if (identity === null) {
			window.MailroomChat.reset();
		} else if (identity && (identity.token || identity.email || identity.name)) {
			window.MailroomChat.identify(identity);
		}
	}, [identity]);

	useEffect(() => {
		if (typeof window === "undefined" || !window.MailroomChat || theme === undefined) return;
		window.MailroomChat.setTheme(theme);
	}, [theme]);

	return null;
}

/** Imperative helpers to open, close, toggle, or reset the Mailroom chat widget from any component. */
export function useMailroomChat() {
	return {
		open: () => (typeof window !== "undefined" ? window.MailroomChat?.open() : undefined),
		close: () => (typeof window !== "undefined" ? window.MailroomChat?.close() : undefined),
		toggle: () => (typeof window !== "undefined" ? window.MailroomChat?.toggle() : undefined),
		identify: (who: MailroomChatIdentity) =>
			typeof window !== "undefined" ? window.MailroomChat?.identify(who) : undefined,
		reset: () => (typeof window !== "undefined" ? window.MailroomChat?.reset() : undefined),
		unread: () => (typeof window !== "undefined" ? (window.MailroomChat?.unread() ?? 0) : 0),
		setTheme: (theme: "light" | "dark" | null) =>
			typeof window !== "undefined" ? window.MailroomChat?.setTheme(theme) : undefined,
	};
}
